// Vector001: fixed-point 3D vector arithmetic: sums, cross products and dot products of random vectors.
// Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
namespace Baseline.Group0;

public static class Vector001
{
    private readonly record struct Vec3(ulong X, ulong Y, ulong Z)
    {
        public Vec3 Add(Vec3 other) => new(X + other.X, Y + other.Y, Z + other.Z);

        public Vec3 Scale(ulong factor) => new(X * factor, Y * factor, Z * factor);

        public ulong Dot(Vec3 other) => X * other.X + Y * other.Y + Z * other.Z;

        public Vec3 Cross(Vec3 other) =>
            new(Y * other.Z - Z * other.Y, Z * other.X - X * other.Z, X * other.Y - Y * other.X);
    }

    private static ulong Simulate(ulong seed)
    {
        var rng = new Rng(seed);
        var sum = new Vec3(0, 0, 0);
        for (int i = 0; i < 22; i++)
        {
            ulong x = rng.Next();
            ulong y = rng.Next();
            ulong z = rng.Next();
            var v = new Vec3(x, y, z);
            var w = v.Cross(sum).Add(v.Scale(0x46FC33FF15BEF56BUL));
            sum = sum.Add(w);
            if ((sum.Dot(v) & 1) == 1)
                sum = sum.Scale(0xDD4AAB4072C7E9UL);
        }
        return sum.Dot(sum) ^ sum.X;
    }

    private static ulong KernelA(ulong x, ulong y)
    {
        ulong a = x & (y << 6);
        ulong b = y >> 47;
        for (ulong i = 0; i < 6; i++)
        {
            a = (a + i) * (i ^ b);
            b = b * Common.Rotl(i << 49, 12);
            if (((a - 156UL) & 1023UL) != 523UL)
            {
                a = a | ((b | 0x3376D34B666D4591UL) % 728UL);
            }
            else
            {
                b = (b * a) + (b ^ 154UL);
            }
        }
        if (((b * x) & 1023UL) == 529UL)
        {
            a = a & ((b - 88UL) >> 26);
        }
        else
        {
            b = b | (a + x);
        }
        ulong c = x + (b * 55UL);
        return c ^ (a + b);
    }

    private static ulong KernelB(ulong x, ulong y)
    {
        ulong a = Common.Rotl(x, 27);
        ulong b = y & 255UL;
        for (ulong i = 0; i < 6; i++)
        {
            a = a - ((b + x) + (b & 118UL));
            b = Common.Rotl(b, 18) - (b << 21);
            if (((i ^ b) & 65535UL) > 34281UL)
            {
                a = a - ((i >> 55) + 0xA01421F728036A41UL);
            }
            else
            {
                b = Common.Rotl(b * 158UL, 12);
            }
        }
        ulong c = Common.Rotl(a, 16) << 8;
        ulong d = (b << 1) & (a ^ 40UL);
        return (c ^ (a ^ b)) + d;
    }

    public static ulong Mix(ulong x) => KernelB(KernelA(x, 0x339596C5AC4F1FB1UL), x ^ 0x3A486CEBCEFA48B7UL);

    public static ulong Run(ulong seed)
    {
        ulong r = Simulate(seed ^ 0xD0F1527C73B2EFBDUL);
        return Mix(r);
    }
}
